import { cn } from "@growtube/ui/lib/utils";

/**
 * GrowTube mark: a green "G" whose tail rises into an arrow, around a play
 * button. public/logo.png is generated by apps/extension/scripts/generate-icons.mjs.
 */
export function LogoMark({ className }: { className?: string }) {
	return (
		<img
			src="/logo.png"
			alt=""
			aria-hidden="true"
			width={28}
			height={28}
			draggable={false}
			className={cn("size-7 shrink-0 select-none", className)}
		/>
	);
}

export function Logo({ className }: { className?: string }) {
	return (
		<span className={cn("inline-flex items-center gap-2", className)}>
			<LogoMark />
			<span className="text-sm font-semibold tracking-tight">GrowTube</span>
		</span>
	);
}
